    var canvas = document.createElement("canvas");
    var gl = canvas.getContext && canvas.getContext("webgl2");
    if (!gl || !gl.getExtension("EXT_color_buffer_float")) {
      hero.querySelector("[data-wth-logo]").removeAttribute("data-wth-logo");
      hero.querySelector(".wth-blog-hero").classList.add("wth-blog-hero--no-webgl");
    }
    var lose = gl && gl.getExtension("WEBGL_lose_context");
    if (lose) lose.loseContext();
    image.replaceWith(hero);
